var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# Provisions the kcov container and runs the bats suite inside it."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# The container side of bin/coverage/run-coverage.sh, which mounts the repository at /src and invokes"},
{"lineNum":"    6","line":"# this. A file rather than a string passed to `bash -c`: the provisioning is twenty lines of shell with"},
{"lineNum":"    7","line":"# its own reasoning to record, and inside a quoted argument none of it can be linted by ShellCheck,"},
{"lineNum":"    8","line":"# indented for reading, or commented without the comment ending up in the wrong shell. It also cannot"},
{"lineNum":"    9","line":"# hold an apostrophe without the \'\"\'\"\' dance, which is how a note about mikefarah came to be written"},
{"lineNum":"   10","line":"# three quotes deep."},
{"lineNum":"   11","line":"#"},
{"lineNum":"   12","line":"# Expects the repository at /src and reads BATS_VERSION, YQ_VERSION and JUNIT_DIR from the environment,"},
{"lineNum":"   13","line":"# which run-coverage.sh passes through so both sides agree on the pinned versions."},
{"lineNum":"   14","line":"#"},
{"lineNum":"   15","line":"# Usage: bash /src/bin/coverage/in-container.sh"},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Guarded at the bottom so the test suite can source it and call one function at a time; unguarded, a"},
{"lineNum":"   18","line":"# source would apt-get its way through a developer machine."},
{"lineNum":"   19","line":""},
{"lineNum":"   20","line":"set -o errexit","class":"lineCov","hits":"1","order":"5256",},
{"lineNum":"   21","line":"set -o nounset","class":"lineCov","hits":"1","order":"5260",},
{"lineNum":"   22","line":"set -o pipefail","class":"lineCov","hits":"1","order":"5267",},
{"lineNum":"   23","line":""},
{"lineNum":"   24","line":"# Every path this writes to is a seam, and that is a safety mechanism rather than a convenience: the"},
{"lineNum":"   25","line":"# defaults are a container\'s own filesystem, so a test that ran the real steps against them would install"},
{"lineNum":"   26","line":"# into the developer\'s /usr/local and extract into their /tmp. One did, before these existed."},
{"lineNum":"   27","line":"#"},
{"lineNum":"   28","line":"# bats is a seam for a different reason — it cannot be stubbed on PATH under its own name, since the"},
{"lineNum":"   29","line":"# coverage harness tracing the test would pick that up instead of the real one."},
{"lineNum":"   30","line":": \"${SRC:=/src}\"","class":"lineCov","hits":"1","order":"5263",},
{"lineNum":"   31","line":": \"${TMP:=/tmp}\"","class":"lineCov","hits":"1","order":"5264",},
{"lineNum":"   32","line":": \"${PREFIX:=/usr/local}\"","class":"lineCov","hits":"1","order":"5265",},
{"lineNum":"   33","line":": \"${BATS_BIN:=bats}\"","class":"lineCov","hits":"1","order":"5258",},
{"lineNum":"   34","line":"readonly SRC TMP PREFIX BATS_BIN","class":"lineCov","hits":"1","order":"5262",},
{"lineNum":"   35","line":""},
{"lineNum":"   36","line":"# wget fetches bats and yq; the rest are what the scripts under test shell out to, and a suite covering a"},
{"lineNum":"   37","line":"# script that needs one fails for want of the tool rather than for a fault in the code. Keep this in step"},
{"lineNum":"   38","line":"# with what the suites exercise."},
{"lineNum":"   39","line":"#"},
{"lineNum":"   40","line":"# procps is for bats, not for the scripts: its per-test timeout shells out to ps/pkill, and without them"},
{"lineNum":"   41","line":"# every test in a file that sets BATS_TEST_TIMEOUT aborts with \"Cannot execute timeout\"."},
{"lineNum":"   42","line":"#"},
{"lineNum":"   43","line":"# git is for the release suites: they drive real repositories rather than stubbing git, because what they"},
{"lineNum":"   44","line":"# check is that a fetch-reset really discards a failed commit and a rejected push really retries."},
{"lineNum":"   45","line":"readonly PACKAGES=(wget libxml2-utils zip unzip jq procps git)","class":"lineCov","hits":"1","order":"5266",},
{"lineNum":"   46","line":""},
{"lineNum":"   47","line":"#######################################"},
{"lineNum":"   48","line":"# Installs the packages the suites need."},
{"lineNum":"   49","line":"#######################################"},
{"lineNum":"   50","line":"install_packages() {"},
{"lineNum":"   51","line":"  apt-get update -qq >/dev/null","class":"lineCov","hits":"1","order":"5268",},
{"lineNum":"   52","line":"  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \"${PACKAGES[@]}\" >/dev/null","class":"lineCov","hits":"1","order":"5271",},
{"lineNum":"   53","line":"}"},
{"lineNum":"   54","line":""},
{"lineNum":"   55","line":"#######################################"},
{"lineNum":"   56","line":"# Installs bats from source at the pinned version."},
{"lineNum":"   57","line":"#"},
{"lineNum":"   58","line":"# Not the distribution package: Debian ships 1.8, which predates BATS_TEST_TIMEOUT, so a suite bounding a"},
{"lineNum":"   59","line":"# test to turn a runaway loop into a failure would silently have no bound here while having one locally."},
{"lineNum":"   60","line":"# Globals:"},
{"lineNum":"   61","line":"#   BATS_VERSION, TMP, PREFIX"},
{"lineNum":"   62","line":"#######################################"},
{"lineNum":"   63","line":"install_bats() {"},
{"lineNum":"   64","line":"  wget -qO \"${TMP}/bats.tar.gz\" \"https://github.com/bats-core/bats-core/archive/refs/tags/${BATS_VERSION}.tar.gz\"","class":"lineCov","hits":"1","order":"5270",},
{"lineNum":"   65","line":"  tar -xzf \"${TMP}/bats.tar.gz\" -C \"${TMP}\"","class":"lineCov","hits":"1","order":"5272",},
{"lineNum":"   66","line":"  \"${TMP}/bats-core-${BATS_VERSION#v}/install.sh\" \"${PREFIX}\" >/dev/null","class":"lineCov","hits":"1","order":"5254",},
{"lineNum":"   67","line":"}"},
{"lineNum":"   68","line":""},
{"lineNum":"   69","line":"#######################################"},
{"lineNum":"   70","line":"# Installs mikefarah\'s yq at the pinned version."},
{"lineNum":"   71","line":"#"},
{"lineNum":"   72","line":"# The distribution package named yq is the Python jq wrapper, which does not speak the v4 expressions the"},
{"lineNum":"   73","line":"# packaging scripts use — so it is fetched rather than installed, at the version the workflows pin."},
{"lineNum":"   74","line":"# Globals:"},
{"lineNum":"   75","line":"#   YQ_VERSION, PREFIX"},
{"lineNum":"   76","line":"#######################################"},
{"lineNum":"   77","line":"install_yq() {"},
{"lineNum":"   78","line":"  wget -qO \"${PREFIX}/bin/yq\" \"https://github.com/mikefarah/yq/releases/download/${YQ_VERSION}/yq_linux_$(dpkg --print-architecture)\"","class":"lineCov","hits":"1","order":"5255",},
{"lineNum":"   79","line":"  chmod +x \"${PREFIX}/bin/yq\"","class":"lineCov","hits":"1","order":"5259",},
{"lineNum":"   80","line":"}"},
{"lineNum":"   81","line":""},
{"lineNum":"   82","line":"#######################################"},
{"lineNum":"   83","line":"# Runs the suite under kcov and leaves its output readable outside the container."},
{"lineNum":"   84","line":"#"},
{"lineNum":"   85","line":"# The container runs as root, so what it writes into the mounted tree would otherwise be unreadable to"},
{"lineNum":"   86","line":"# the host user and to the CI steps that publish it."},
{"lineNum":"   87","line":"# Globals:"},
{"lineNum":"   88","line":"#   JUNIT_DIR"},
{"lineNum":"   89","line":"#######################################"},
{"lineNum":"   90","line":"run_suite() {"},
{"lineNum":"   91","line":"  local report=()","class":"lineCov","hits":"1","order":"5257",},
{"lineNum":"   92","line":"  if [[ -n \"${JUNIT_DIR:-}\" ]]; then","class":"lineCov","hits":"1","order":"5261",},
{"lineNum":"   93","line":"    report=(--report-formatter junit --output \"${SRC}/${JUNIT_DIR}\")","class":"lineCov","hits":"1","order":"5269",},
{"lineNum":"   94","line":"  fi"},
{"lineNum":"   95","line":""},
{"lineNum":"   96","line":"  COVERAGE_DIR=\"${SRC}/coverage\" ${BATS_BIN} --recursive \"${report[@]}\" test/","class":"lineCov","hits":"1","order":"5253",},
{"lineNum":"   97","line":""},
{"lineNum":"   98","line":"  chmod -R a+rX \"${SRC}/coverage\"","class":"lineCov","hits":"1","order":"5252",},
{"lineNum":"   99","line":"  if [[ -n \"${JUNIT_DIR:-}\" ]]; then","class":"lineCov","hits":"1","order":"5251",},
{"lineNum":"  100","line":"    chmod -R a+rX \"${SRC}/${JUNIT_DIR}\"","class":"lineCov","hits":"1","order":"5250",},
{"lineNum":"  101","line":"  fi"},
{"lineNum":"  102","line":"}"},
{"lineNum":"  103","line":""},
{"lineNum":"  104","line":"# Guarded so the suite can source this file and exercise one step at a time."},
{"lineNum":"  105","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"5249",},
{"lineNum":"  106","line":"  install_packages","class":"lineNoCov","hits":"0",},
{"lineNum":"  107","line":"  install_bats","class":"lineNoCov","hits":"0",},
{"lineNum":"  108","line":"  install_yq","class":"lineNoCov","hits":"0",},
{"lineNum":"  109","line":"  run_suite","class":"lineNoCov","hits":"0",},
{"lineNum":"  110","line":"fi"},
]};
